import{_ as o,a as i,c as d,ac as c}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"MySQL数据库设计规范 · 1. 规范背景与目的至2. 设计规范","description":"历史 MySQL 库表、索引、分片与 SQL 审核规则","frontmatter":{"title":"MySQL数据库设计规范 · 1. 规范背景与目的至2. 设计规范","description":"历史 MySQL 库表、索引、分片与 SQL 审核规则","splitFrom":"middleware/mysql/plus/practice/mysql设计规范.md","showdocs":{"topics":[{"id":"mysql","title":"MySQL","link":"/topics/mysql/"},{"id":"architecture","title":"架构风格与模块边界","link":"/topics/architecture/"}],"kind":"应用实践","scope":"historical","audience":"general","group":"数据库与存储","seriesTitle":"MySQL数据库设计规范","summary":"历史 MySQL 库表、索引、分片与 SQL 审核规则","status":"active","related":[{"title":"MySQL数据库设计规范","link":"/middleware/mysql/plus/practice/mysql%E8%AE%BE%E8%AE%A1%E8%A7%84%E8%8C%83","kind":"应用实践","scope":"historical","audience":"general"},{"title":"MySQL数据库设计规范 · 2.1.7 程序层DAO设计建议至2.2 SQL编写","link":"/middleware/mysql/plus/practice/mysql设计规范-part-02","kind":"应用实践","scope":"historical","audience":"general"},{"title":"朋友圈（广场设计）","link":"/principles/distributed-architecture/architecture/cases/%E6%9C%8B%E5%8F%8B%E5%9C%88(%E5%B9%BF%E5%9C%BA%E8%AE%BE%E8%AE%A1)","kind":"架构取舍与原文","scope":"historical","audience":"general"},{"title":"Redis：数据结构服务、缓存与部署边界","link":"/middleware/redis/foundations","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis：数据结构服务、缓存与部署边界 · 缓存异常至延伸阅读","link":"/middleware/redis/foundations-part-03","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":{"text":"MySQL数据库设计规范","link":"/middleware/mysql/plus/practice/mysql%E8%AE%BE%E8%AE%A1%E8%A7%84%E8%8C%83"},"next":{"text":"MySQL数据库设计规范 · 2.1.7 程序层DAO设计建议至2.2 SQL编写","link":"/middleware/mysql/plus/practice/mysql设计规范-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"MySQL数据库设计规范","link":"/middleware/mysql/plus/practice/mysql%E8%AE%BE%E8%AE%A1%E8%A7%84%E8%8C%83"},"next":{"text":"MySQL数据库设计规范 · 2.1.7 程序层DAO设计建议至2.2 SQL编写","link":"/middleware/mysql/plus/practice/mysql设计规范-part-02"}},"headers":[],"relativePath":"middleware/mysql/plus/practice/mysql设计规范-part-01.md","filePath":"middleware/mysql/plus/practice/mysql设计规范-part-01.md"}'),l={name:"middleware/mysql/plus/practice/mysql设计规范-part-01.md"};function a(t,e,r,n,s,m){return i(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="mysql数据库设计规范-·-1-规范背景与目的至2-设计规范" tabindex="-1">MySQL数据库设计规范 · 1. 规范背景与目的至2. 设计规范 <a class="header-anchor" href="#mysql数据库设计规范-·-1-规范背景与目的至2-设计规范" aria-label="Permalink to &quot;MySQL数据库设计规范 · 1. 规范背景与目的至2. 设计规范&quot;">​</a></h1><p><a href="/middleware/mysql/plus/practice/mysql设计规范">返回分篇目录</a></p><h2 id="mysql数据库设计规范" tabindex="-1">MySQL数据库设计规范 <a class="header-anchor" href="#mysql数据库设计规范" aria-label="Permalink to &quot;MySQL数据库设计规范 {#mysql数据库设计规范}&quot;">​</a></h2><p><span id="目录"></span></p><h2 id="_1-规范背景与目的" tabindex="-1">1. 规范背景与目的 <a class="header-anchor" href="#_1-规范背景与目的" aria-label="Permalink to &quot;1. 规范背景与目的 {#_1-规范背景与目的}&quot;">​</a></h2><p>MySQL数据库与 Oracle、 SQL Server 等数据库相比，有其内核上的优势与劣势。我们在使用MySQL数据库的时候需要遵循一定规范，扬长避短。本规范旨在帮助或指导RD、QA、OP等技术人员做出适合线上业务的数据库设计。在数据库变更和处理流程、数据库表设计、SQL编写等方面予以规范，从而为公司业务系统稳定、健康地运行提供保障。</p><h2 id="_2-设计规范" tabindex="-1">2. 设计规范 <a class="header-anchor" href="#_2-设计规范" aria-label="Permalink to &quot;2. 设计规范 {#_2-设计规范}&quot;">​</a></h2><h3 id="_2-1-数据库设计" tabindex="-1">2.1 数据库设计 <a class="header-anchor" href="#_2-1-数据库设计" aria-label="Permalink to &quot;2.1 数据库设计 {#_2-1-数据库设计}&quot;">​</a></h3><p>以下所有规范会按照【高危】、【强制】、【建议】三个级别进行标注，遵守优先级从高到低。</p><p>对于不满足【高危】和【强制】两个级别的设计，DBA会强制打回要求修改。</p><h3 id="_2-1-1-库名" tabindex="-1">2.1.1 库名 <a class="header-anchor" href="#_2-1-1-库名" aria-label="Permalink to &quot;2.1.1 库名 {#_2-1-1-库名}&quot;">​</a></h3><ol><li>【强制】库的名称必须控制在32个字符以内，相关模块的表名与表名之间尽量提现join的关系，如user表和user_login表。</li><li>【强制】库的名称格式：业务系统名称_子系统名，同一模块使用的表名尽量使用统一前缀。</li><li>【强制】一般分库名称命名格式是<code>库通配名_编号</code>，编号从0开始递增，比如<code>wenda_001</code>以时间进行分库的名称格式是“库通配名_时间”</li><li>【强制】创建数据库时必须显式指定字符集，并且字符集只能是utf8或者utf8mb4。创建数据库SQL举例：<code>create database db1 default character set utf8;</code>。</li></ol><h3 id="_2-1-2-表结构" tabindex="-1">2.1.2 表结构 <a class="header-anchor" href="#_2-1-2-表结构" aria-label="Permalink to &quot;2.1.2 表结构 {#_2-1-2-表结构}&quot;">​</a></h3><ol><li>【强制】表和列的名称必须控制在32个字符以内，表名只能使用字母、数字和下划线，一律小写。</li><li>【强制】表名要求模块名强相关，如师资系统采用”sz”作为前缀，渠道系统采用”qd”作为前缀等。</li><li>【强制】创建表时必须显式指定字符集为utf8或utf8mb4。</li><li>【强制】创建表时必须显式指定表存储引擎类型，如无特殊需求，一律为InnoDB。当需要使用除InnoDB/MyISAM/Memory以外的存储引擎时，必须通过DBA审核才能在生产环境中使用。因为Innodb表支持事务、行锁、宕机恢复、MVCC等关系型数据库重要特性，为业界使用最多的MySQL存储引擎。而这是其他大多数存储引擎不具备的，因此首推InnoDB。</li><li>【强制】建表必须有comment</li><li>【建议】建表时关于主键：(1)强制要求主键为id，类型为int或bigint，且为<code>auto_increment(2)</code>标识表里每一行主体的字段不要设为主键，建议设为其他字段如<code>user_id</code>，<code>order_id</code>等，并建立unique key索引（可参考<code>cdb.teacher</code>表设计）。因为如果设为主键且主键值为随机插入，则会导致innodb内部page分裂和大量随机I/O，性能下降。</li><li>【建议】核心表（如用户表，金钱相关的表）必须有行数据的创建时间字段<code>create_time</code>和最后更新时间字段<code>update_time</code>，便于查问题。</li><li>【建议】表中所有字段必须都是<code>NOT NULL</code>属性，业务可以根据需要定义<code>DEFAULT</code>值。因为使用NULL值会存在每一行都会占用额外存储空间、数据迁移容易出错、聚合函数计算结果偏差等问题。</li><li>【建议】建议对表里的<code>blob</code>、<code>text</code>等大字段，垂直拆分到其他表里，仅在需要读这些对象的时候才去select。</li><li>【建议】反范式设计：把经常需要join查询的字段，在其他表里冗余一份。如<code>user_name</code>属性在<code>user_account</code>，<code>user_login_log</code>等表里冗余一份，减少join查询。</li><li>【强制】中间表用于保留中间结果集，名称必须以<code>tmp_</code>开头。备份表用于备份或抓取源表快照，名称必须以<code>bak_</code>开头。中间表和备份表定期清理。</li><li>【强制】对于超过100W行的大表进行<code>alter table</code>，必须经过DBA审核，并在业务低峰期执行。因为<code>alter table</code>会产生表锁，期间阻塞对于该表的所有写入，对于业务可能会产生极大影响。</li></ol><h3 id="_2-1-3-列数据类型优化" tabindex="-1">2.1.3 列数据类型优化 <a class="header-anchor" href="#_2-1-3-列数据类型优化" aria-label="Permalink to &quot;2.1.3 列数据类型优化 {#_2-1-3-列数据类型优化}&quot;">​</a></h3><ol><li>【建议】表中的自增列（<code>auto_increment</code>属性），推荐使用<code>bigint</code>类型。因为无符号<code>int</code>存储范围为<code>-2147483648~2147483647</code>（大约21亿左右），溢出后会导致报错。</li><li>【建议】业务中选择性很少的状态<code>status</code>、类型<code>type</code>等字段推荐使用<code>tinytint</code>或者<code>smallint</code>类型节省存储空间。</li><li>【建议】业务中IP地址字段推荐使用<code>int</code>类型，不推荐用<code>char(15)</code>。因为<code>int</code>只占4字节，可以用如下函数相互转换，而<code>char(15)</code>占用至少15字节。一旦表数据行数到了1亿，那么要多用1.1G存储空间。 SQL：<code>select inet_aton(&#39;192.168.2.12&#39;); select inet_ntoa(3232236044);</code> PHP: <code>ip2long(&#39;192.168.2.12&#39;); long2ip(3530427185);</code></li><li>【建议】不推荐使用<code>enum</code>，<code>set</code>。 因为它们浪费空间，且枚举值写死了，变更不方便。推荐使用<code>tinyint</code>或<code>smallint</code>。</li><li>【建议】不推荐使用<code>blob</code>，<code>text</code>等类型。它们都比较浪费硬盘和内存空间。在加载表数据时，会读取大字段到内存里从而浪费内存空间，影响系统性能。建议和PM、RD沟通，是否真的需要这么大字段。Innodb中当一行记录超过8098字节时，会将该记录中选取最长的一个字段将其768字节放在原始page里，该字段余下内容放在<code>overflow-page</code>里。不幸的是在<code>compact</code>行格式下，原始<code>page</code>和<code>overflow-page</code>都会加载。</li><li>【建议】存储金钱的字段，建议用<code>int</code>，程序端乘以100和除以100进行存取。因为<code>int</code>占用4字节，而<code>double</code>占用8字节，空间浪费。</li><li>【建议】文本数据尽量用<code>varchar</code>存储。因为<code>varchar</code>是变长存储，比<code>char</code>更省空间。MySQL server层规定一行所有文本最多存65535字节，因此在utf8字符集下最多存21844个字符，超过会自动转换为<code>mediumtext</code>字段。而<code>text</code>在utf8字符集下最多存21844个字符，<code>mediumtext</code>最多存2^24/3个字符，<code>longtext</code>最多存2^32个字符。一般建议用<code>varchar</code>类型，字符数不要超过2700。</li><li>【建议】时间类型尽量选取<code>timestamp</code>。因为<code>datetime</code>占用8字节，<code>timestamp</code>仅占用4字节，但是范围为<code>1970-01-01 00:00:01</code>到<code>2038-01-01 00:00:00</code>。更为高阶的方法，选用<code>int</code>来存储时间，使用SQL函数<code>unix_timestamp()</code>和<code>from_unixtime()</code>来进行转换。</li></ol><h3 id="_2-1-4-索引设计" tabindex="-1">2.1.4 索引设计 <a class="header-anchor" href="#_2-1-4-索引设计" aria-label="Permalink to &quot;2.1.4 索引设计 {#_2-1-4-索引设计}&quot;">​</a></h3><ol><li>【强制】InnoDB表必须主键为<code>id int/bigint auto_increment</code>,且主键值禁止被更新。</li><li>【建议】主键的名称以“<code>pk_</code>”开头，唯一键以“<code>uk_</code>”或“<code>uq_</code>”开头，普通索引以“<code>idx_</code>”开头，一律使用小写格式，以表名/字段的名称或缩写作为后缀。</li><li>【强制】InnoDB和MyISAM存储引擎表，索引类型必须为<code>BTREE</code>；MEMORY表可以根据需要选择<code>HASH</code>或者<code>BTREE</code>类型索引。</li><li>【强制】单个索引中每个索引记录的长度不能超过64KB。</li><li>【建议】单个表上的索引个数不能超过7个。</li><li>【建议】在建立索引时，多考虑建立联合索引，并把区分度最高的字段放在最前面。如列<code>userid</code>的区分度可由<code>select count(distinct userid)</code>计算出来。</li><li>【建议】在多表join的SQL里，保证被驱动表的连接列上有索引，这样join执行效率最高。</li><li>【建议】建表或加索引时，保证表里互相不存在冗余索引。对于MySQL来说，如果表里已经存在<code>key(a,b)</code>，则<code>key(a)</code>为冗余索引，需要删除。</li></ol><h3 id="_2-1-5-分库分表、分区表" tabindex="-1">2.1.5 分库分表、分区表 <a class="header-anchor" href="#_2-1-5-分库分表、分区表" aria-label="Permalink to &quot;2.1.5 分库分表、分区表 {#_2-1-5-分库分表、分区表}&quot;">​</a></h3><ol><li>【强制】分区表的分区字段（<code>partition-key</code>）必须有索引，或者是组合索引的首列。</li><li>【强制】单个分区表中的分区（包括子分区）个数不能超过1024。</li><li>【强制】上线前RD或者DBA必须指定分区表的创建、清理策略。</li><li>【强制】访问分区表的SQL必须包含分区键。</li><li>【建议】单个分区文件不超过2G，总大小不超过50G。建议总分区数不超过20个。</li><li>【强制】对于分区表执行<code>alter table</code>操作，必须在业务低峰期执行。</li><li>【强制】采用分库策略的，库的数量不能超过1024</li><li>【强制】采用分表策略的，表的数量不能超过4096</li><li>【建议】单个分表不超过500W行，ibd文件大小不超过2G，这样才能让数据分布式变得性能更佳。</li><li>【建议】水平分表尽量用取模方式，日志、报表类数据建议采用日期进行分表。</li></ol><h3 id="_2-1-6-字符集" tabindex="-1">2.1.6 字符集 <a class="header-anchor" href="#_2-1-6-字符集" aria-label="Permalink to &quot;2.1.6 字符集 {#_2-1-6-字符集}&quot;">​</a></h3><ol><li>【强制】数据库本身库、表、列所有字符集必须保持一致，为<code>utf8</code>或<code>utf8mb4</code>。</li><li>【强制】前端程序字符集或者环境变量中的字符集，与数据库、表的字符集必须一致，统一为<code>utf8</code>。</li></ol>',22)])])}const _=o(l,[["render",a]]);export{p as __pageData,_ as default};
